content.query:
let latestDevices = DeviceInfo
| where TimeGenerated > ago(30d)
| summarize arg_max(TimeGenerated, MachineGroup, IsInternetFacing, OSPlatform, OSVersion) by DeviceId, DeviceName
| extend GroupName = iff(isempty(MachineGroup), 'Unassigned', MachineGroup)
| where ('*' in ({DeviceGroup}) or GroupName in ({DeviceGroup}))
| where ('{ExposureFilter}' == 'All' or ('{ExposureFilter}' == 'InternetFacing' and IsInternetFacing == true) or ('{ExposureFilter}' == 'InternalOnly' and IsInternetFacing != true));
let kb = DeviceTvmSoftwareVulnerabilitiesKB
| summarize arg_max(TimeGenerated, PublishedDate, IsExploitAvailable, VulnerabilitySeverityLevel, CvssScore) by CveId;
let vulns = DeviceTvmSoftwareVulnerabilities
| where TimeGenerated > ago(14d)
| summarize arg_max(TimeGenerated, SoftwareVendor, SoftwareName, SoftwareVersion, VulnerabilitySeverityLevel, RecommendedSecurityUpdate, CveTags) by DeviceId, DeviceName, CveId
| join kind=inner latestDevices on DeviceId
| join kind=leftouter kb on CveId
| extend AgeHours = datetime_diff('hour', now(), coalesce(PublishedDate, TimeGenerated))
| extend IsExploited = (IsExploitAvailable == true or tostring(CveTags) has_any ('ZeroDay', 'ExploitInTheWild', 'CISA_KEV'))
| extend IsOS = (SoftwareName has_any ('windows', 'ubuntu', 'rhel', 'debian', 'centos', 'macos', 'linux_kernel', 'server'))
| extend IsCoreApp = (not(IsOS) and (SoftwareName has_any ('chrome', 'edge', 'firefox', 'safari', 'office', 'word', 'excel', 'outlook', 'acrobat', 'reader', 'foxit', 'defender', 'crowdstrike', 'sentinelone', '7zip', 'java', 'zoom', 'teams')));
let overdueExploited = vulns | where (IsExploited or VulnerabilitySeverityLevel == 'Critical') and AgeHours > 48 | summarize Metric = 'Overdue Critical / Exploited (>48h)', Value = dcount(strcat(DeviceId, CveId));
let overdueCoreApps = vulns | where IsCoreApp and AgeHours > (14 * 24) | summarize Metric = 'Overdue Core Apps (>14d)', Value = dcount(strcat(DeviceId, CveId));
let overdueOtherApps = vulns | where not(IsOS) and not(IsCoreApp) and AgeHours > iff('{TargetML}' == 'ML3', 14 * 24, 30 * 24) | summarize Metric = 'Overdue Other Apps (ML SLA)', Value = dcount(strcat(DeviceId, CveId));
let overdueOS = vulns | where IsOS and AgeHours > iff(IsInternetFacing == true or '{TargetML}' == 'ML3', 14 * 24, 30 * 24) | summarize Metric = 'Overdue OS Patches (ML SLA)', Value = dcount(strcat(DeviceId, CveId));
union overdueExploited, overdueCoreApps, overdueOtherApps, overdueOS
